166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
169	        Collection<Owner> owners;
170	        if (lastName != null) {
171	            owners = this.clinicService.findOwnerByLastName(lastName);
172	        } else {
173	            owners = this.clinicService.findAllOwners();
174	        }
175	        if (owners.isEmpty()) {
176	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
177	        }
178	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
179	    }
180	
181	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
182	    @Override
183	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
184	        Owner owner = this.clinicService.findOwnerById(ownerId);
185	        if (owner == null) {
186	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
187	        }
188	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
189	    }
190	
191	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
192	    @Override
193	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto, String idempotencyKey) {
194	        ResponseEntity<OwnerDto> replay = replayIdempotentCreate(idempotencyKey);
195	        if (replay != null) {
196	            return replay;
197	        }
198	        HttpHeaders headers = new HttpHeaders();
199	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
200	        addressResolver.resolve(owner);
201	        registrationDateValidator.validate(owner.getRegistrationDate());
202	        LocalDate registrationDate = owner.getRegistrationDate() != null
203	            ? owner.getRegistrationDate() : LocalDate.now();
204	        owner.setRegistrationDate(businessDayAdjuster.toBusinessDay(registrationDate));
205	        owner.setTelephone(telephoneNormalizer.normalize(owner.getTelephone()));
206	        owner.setEmail(emailNormalizer.normalize(owner.getEmail()));
207	        dailyRegistrationLimitValidator.validate(owner.getRegistrationDate());
208	        cityCapacityValidator.validate(owner);
209	        owner.setHouseholdId(households.householdId(owner));
210	        duplicateIdentityValidator.validate(owner);
211	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
212	        if (sharesHousehold) {
213	            // A declared household member is not a suspected duplicate.
214	            owner.setPossibleDuplicate(false);
215	        } else {
216	            possibleDuplicateDetector.detect(owner);
217	        }
218	        this.clinicService.saveOwner(owner);
219	        ownerAuditLogger.logCreated(owner);
220	        welcomeNotifier.enqueueWelcome(owner);
221	        ownerIdempotencyStore.record(idempotencyKey, owner.getId());
222	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
223	        headers.setLocation(UriComponentsBuilder.newInstance()
224	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
225	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
226	    }
227	
228	    /**
229	     * If {@code idempotencyKey} has already been used to create an owner that still exists, returns
230	     * that originally created owner with 200 so the repeated create is a no-op; otherwise returns
231	     * {@code null} to let the create proceed normally.
232	     */
233	    private ResponseEntity<OwnerDto> replayIdempotentCreate(String idempotencyKey) {
234	        return ownerIdempotencyStore.find(idempotencyKey)
235	            .map(this.clinicService::findOwnerById)
236	            .map(owner -> new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK))
237	            .orElse(null);
238	    }
239	
240	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
241	    @Override
242	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
243	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
244	        if (currentOwner == null) {
245	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
246	        }
247	        currentOwner.setAddress(ownerFieldsDto.getAddress());
248	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
249	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
250	        addressResolver.resolve(currentOwner);
251	        currentOwner.setCity(ownerFieldsDto.getCity());
252	        currentOwner.setTitle(ownerFieldsDto.getTitle() == null ? null : ownerFieldsDto.getTitle().getValue());
253	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
254	        currentOwner.setLastName(ownerFieldsDto.getLastName());
255	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
256	        currentOwner.setEmail(emailNormalizer.normalize(ownerFieldsDto.getEmail()));
257	        this.clinicService.saveOwner(currentOwner);
258	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
259	    }
260	
261	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
262	    @Transactional
263	    @Override
264	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
265	        Owner owner = this.clinicService.findOwnerById(ownerId);
266	        if (owner == null) {
267	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
268	        }
269	        this.clinicService.deleteOwner(owner);
270	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
271	    }
272	
273	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
274	    @Override
275	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
276	        Owner owner = this.clinicService.findOwnerById(ownerId);
277	        if (owner == null) {
278	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	        }
280	        HttpHeaders headers = new HttpHeaders();
281	        Pet pet = petMapper.toPet(petFieldsDto);
282	        owner.setId(ownerId);
283	        pet.setOwner(owner);
284	        pet.getType().setName(null);
285	        this.clinicService.savePet(pet);
286	        PetDto petDto = petMapper.toPetDto(pet);
287	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
288	            .buildAndExpand(pet.getId()).toUri());
289	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
290	    }
291	
292	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
293	    @Override
294	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
295	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
296	        if (currentOwner != null) {
297	            Pet currentPet = this.clinicService.findPetById(petId);
298	            if (currentPet != null) {
299	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
300	                currentPet.setName(petFieldsDto.getName());
301	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
302	                this.clinicService.savePet(currentPet);
303	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
304	            }
305	        }
306	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
307	    }
308	
309	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
310	    @Override
311	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
312	        HttpHeaders headers = new HttpHeaders();
313	        Visit visit = visitMapper.toVisit(visitFieldsDto);
314	        Pet pet = new Pet();
315	        pet.setId(petId);
316	        visit.setPet(pet);
317	        this.clinicService.saveVisit(visit);
318	        VisitDto visitDto = visitMapper.toVisitDto(visit);
319	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
320	            .buildAndExpand(visit.getId()).toUri());
321	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
322	    }
323	
324	
325	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
326	    @Override
327	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
328	        Owner owner = this.clinicService.findOwnerById(ownerId);
329	        if (owner != null) {
330	            Pet pet = owner.getPet(petId);
331	            if (pet != null) {
332	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
333	            }
334	        }
335	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
336	    }
337	}
