151	    /**
152	     * Whether this owner has a non-blank email address on file.
153	     */
154	    public boolean hasEmail() {
155	        return this.email != null && !this.email.isBlank();
156	    }
157	
158	    public String getPostcode() {
159	        return this.postcode;
160	    }
161	
162	    public void setPostcode(String postcode) {
163	        this.postcode = postcode;
164	    }
165	
166	    public String getMemberId() {
167	        return this.memberId;
168	    }
169	
170	    public void setMemberId(String memberId) {
171	        this.memberId = memberId;
172	    }
173	
174	    public LocalDate getRegistrationDate() {
175	        return this.registrationDate;
176	    }
177	
178	    public void setRegistrationDate(LocalDate registrationDate) {
179	        this.registrationDate = registrationDate;
180	    }
181	
182	    /**
183	     * The owner's tenure, in whole fiscal years (starting 1 July) elapsed from its
184	     * registration date's fiscal year up to the fiscal year containing {@code asOf}.
185	     * Returns 0 when the registration date is absent (as for a brand-new owner) or when
186	     * {@code asOf} falls in an earlier fiscal year than the registration date.
187	     */
188	    public long tenureInFiscalYears(LocalDate asOf) {
189	        if (this.registrationDate == null || asOf == null) {
190	            return 0;
191	        }
192	        int elapsed = FiscalYear.containing(this.registrationDate).yearsUntil(FiscalYear.containing(asOf));
193	        return Math.max(0, elapsed);
194	    }
195	
196	    public LocalDate getBirthDate() {
197	        return this.birthDate;
198	    }
199	
200	    public void setBirthDate(LocalDate birthDate) {
201	        this.birthDate = birthDate;
202	    }
