250	    public void saveOwner(Owner owner) throws DataAccessException {
251	        if (owner.isNew() && owner.getMemberId() == null) {
252	            String region = Locality.forOwner(owner) + OwnerIdentityVersion.TAG;
253	            int fiscalYear = FiscalYear.containing(owner.getRegistrationDate()).shortYear();
254	            String baseId = memberIdGenerator.generate(region, fiscalYear, owner.getTelephone(), owner.getLastName());
255	            List<String> existingIds = ownerRepository.findAll().stream()
256	                .map(Owner::getMemberId)
257	                .filter(Objects::nonNull)
258	                .toList();
259	            owner.setMemberId(memberIdDeduplicator.deDuplicate(baseId, existingIds));
260	        }
261	        if (owner.isNew() && owner.getNamesakeCount() == null) {
262	            Collection<Owner> sameLastName = ownerRepository.findByLastNameIgnoreCase(owner.getLastName());
263	            owner.setNamesakeCount(namesakeCounter.count(owner, sameLastName));
264	        }
265	        ownerRepository.save(owner);
266	    }
