18	
19	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
20	import org.springframework.stereotype.Component;
21	import org.springframework.util.StringUtils;
22	import org.springframework.validation.Errors;
23	import org.springframework.validation.Validator;
24	
25	/**
26	 * Enforces that every mandatory owner field is present and non-blank.
27	 * <p>
28	 * A field is rejected when it is missing (null), empty or whitespace-only. Registered on the
29	 * owner request binder so it runs during the standard {@code @Valid} pass, letting its rejections
30	 * surface through the same {@code BindingResult} as the Bean Validation constraints.
31	 */
32	@Component
33	public class OwnerFieldsValidator implements Validator {
34	
35	    private final AddressResolver addressResolver;
36	
37	    public OwnerFieldsValidator(AddressResolver addressResolver) {
38	        this.addressResolver = addressResolver;
39	    }
40	
41	    @Override
42	    public boolean supports(Class<?> clazz) {
43	        return OwnerFieldsDto.class.isAssignableFrom(clazz);
44	    }
45	
46	    @Override
47	    public void validate(Object target, Errors errors) {
48	        OwnerFieldsDto owner = (OwnerFieldsDto) target;
49	        rejectIfBlank(errors, "firstName", owner.getFirstName());
50	        rejectIfBlank(errors, "lastName", owner.getLastName());
51	        rejectIfMissingAddress(errors, owner);
52	        rejectIfBlank(errors, "city", owner.getCity());
53	        rejectIfBlank(errors, "telephone", owner.getTelephone());
54	    }
55	
56	    /**
57	     * Requires an address in either accepted form: a non-blank structured {@code addressLine1}
58	     * or the flat {@code address}. The rejection is reported against {@code addressLine1}, the
59	     * preferred field, when neither is supplied.
60	     */
61	    private void rejectIfMissingAddress(Errors errors, OwnerFieldsDto owner) {
62	        if (!addressResolver.hasStructuredAddress(owner.getAddressLine1())
63	            && !addressResolver.hasFlatAddress(owner.getAddress())) {
64	            errors.rejectValue("addressLine1", "required", "must not be blank");
65	        }
66	    }
67	
68	    private void rejectIfBlank(Errors errors, String field, String value) {
69	        if (!StringUtils.hasText(value)) {
70	            errors.rejectValue(field, "required", "must not be blank");
71	        }
72	    }
73	}
