19	import java.util.Map;
20	import java.util.Optional;
21	import java.util.concurrent.ConcurrentHashMap;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Remembers which owner was created for each client-supplied {@code Idempotency-Key}, so a create
27	 * that repeats with an already-seen key can return the originally created owner instead of creating
28	 * a duplicate. Keys are held in memory and mapped to the id of the owner first created under them.
29	 */
30	@Component
31	public class OwnerIdempotencyStore {
32	
33	    private final Map<String, Integer> ownerIdByKey = new ConcurrentHashMap<>();
34	
35	    /**
36	     * @return the id of the owner previously created under {@code key}, or empty if the key is
37	     * blank or has not been seen before.
38	     */
39	    public Optional<Integer> find(String key) {
40	        if (key == null || key.isBlank()) {
41	            return Optional.empty();
42	        }
43	        return Optional.ofNullable(ownerIdByKey.get(key));
44	    }
45	
46	    /**
47	     * Records that {@code ownerId} was created under {@code key}. Blank keys are ignored. The first
48	     * owner recorded for a key wins; later creates with the same key resolve to it via {@link #find}.
49	     */
50	    public void record(String key, Integer ownerId) {
51	        if (key == null || key.isBlank()) {
52	            return;
53	        }
54	        ownerIdByKey.putIfAbsent(key, ownerId);
55	    }
56	}
