18	
19	import java.util.regex.Pattern;
20	
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Normalizes a raw telephone input into canonical E.164 form.
25	 * <p>
26	 * Spaces, dashes and brackets are stripped. When the remaining value carries a
27	 * leading {@code '+'} its country code is kept as supplied; otherwise the default
28	 * country code {@link #DEFAULT_COUNTRY_CODE} is assumed and a single leading
29	 * {@code '0'} is dropped from the national digits. The digits following the
30	 * {@code '+'} must number between {@link #MIN_DIGITS} and {@link #MAX_DIGITS}, and the
31	 * national number must also match the length its country calling code requires (see
32	 * {@link E164CountryRules}); anything else is rejected with an
33	 * {@link InvalidTelephoneException} (surfaced as {@code 400 Bad Request}).
34	 */
35	@Component
36	public class TelephoneNormalizer {
37	
38	    private static final String DEFAULT_COUNTRY_CODE = "61";
39	    private static final int MIN_DIGITS = 8;
40	    private static final int MAX_DIGITS = 15;
41	
42	    /** Matches the digits that must follow the '+' once the country code is resolved. */
43	    private static final Pattern E164_DIGITS =
44	        Pattern.compile("\\d{" + MIN_DIGITS + "," + MAX_DIGITS + "}");
45	
46	    private final E164CountryRules countryRules;
47	
48	    public TelephoneNormalizer(E164CountryRules countryRules) {
49	        this.countryRules = countryRules;
50	    }
51	
52	    /**
53	     * Convert {@code rawTelephone} into its E.164 representation.
54	     *
55	     * @param rawTelephone the telephone as supplied by the client (may contain formatting)
56	     * @return the E.164 telephone (a leading {@code '+'} followed by 8-15 digits) to store and return
57	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number
58	     */
59	    public String normalize(String rawTelephone) {
60	        String cleaned = rawTelephone == null ? "" : rawTelephone.replaceAll("[\\s()-]", "");
61	        String digits;
62	        if (cleaned.startsWith("+")) {
63	            digits = cleaned.substring(1);
64	        } else {
65	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
66	            digits = DEFAULT_COUNTRY_CODE + national;
67	        }
68	        if (!E164_DIGITS.matcher(digits).matches()) {
69	            throw InvalidTelephoneException.notE164(rawTelephone);
70	        }
71	        countryRules.validateNationalLength(digits, rawTelephone);
72	        return "+" + digits;
73	    }
74	}
