220	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
221	     */
222	    @ExceptionHandler(MethodArgumentNotValidException.class)
223	    @ResponseBody
224	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
225	        HttpStatus status = HttpStatus.BAD_REQUEST;
226	        BindingErrorsResponse errors = new BindingErrorsResponse();
227	        BindingResult bindingResult = e.getBindingResult();
228	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
229	        if (bindingResult.hasErrors()) {
230	            errors.addAllErrors(bindingResult);
231	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
232	                .map(fieldError -> {
233	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
234	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
235	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
236	                        fieldError.getField(),
237	                        defaultMessage,
238	                        rejectedValue);
239	                    return new ValidationMessageDto(message)
240	                        .putAdditionalProperty("field", fieldError.getField())
241	                        .putAdditionalProperty("rejectedValue", rejectedValue)
242	                        .putAdditionalProperty("defaultMessage", defaultMessage);
243	                })
244	                .toList();
245	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
246	                .map(FieldError::getField)
247	                .distinct()
248	                .toList();
249	            logger.debug("Validation error at {} {}: {}",
250	                request.getMethod(),
251	                request.getRequestURI(),
252	                bindingResult.getFieldErrors());
253	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
254	            detail.setProperty("errors", invalidFields);
255	            return ResponseEntity.status(status).body(detail);
256	        }
257	        return ResponseEntity.status(status).body(detail);
258	    }
