18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.stereotype.Component;
21	
22	/**
23	 * Reconciles an owner's two accepted address forms into the canonical fields stored on the
24	 * {@link Owner}. The structured form ({@code addressLine1} plus optional {@code addressLine2}) is
25	 * preferred whenever a non-blank {@code addressLine1} is supplied; otherwise the flat
26	 * {@code address} input is used, keeping earlier minimal payloads accepted.
27	 * <p>
28	 * Each supplied address field is canonicalized with the shared {@link AddressNormalizer}, and the
29	 * composed {@code address} is set to the normalized {@code addressLine1} with a single space and
30	 * the normalized {@code addressLine2} appended when an {@code addressLine2} is present. The
31	 * normalized structured lines are written back so everything that later reads the address sees the
32	 * structured values when present and the flat address otherwise.
33	 */
34	@Component
35	public class AddressResolver {
36	
37	    private final AddressNormalizer addressNormalizer;
38	
39	    public AddressResolver(AddressNormalizer addressNormalizer) {
40	        this.addressNormalizer = addressNormalizer;
41	    }
42	
43	    /**
44	     * Whether {@code addressLine1} carries a usable structured address once normalized.
45	     */
46	    public boolean hasStructuredAddress(String addressLine1) {
47	        return !addressNormalizer.normalize(addressLine1).isEmpty();
48	    }
49	
50	    /**
51	     * Whether the flat {@code address} input carries a usable address once normalized.
52	     */
53	    public boolean hasFlatAddress(String address) {
54	        return !addressNormalizer.normalize(address).isEmpty();
55	    }
56	
57	    /**
58	     * Normalizes {@code owner}'s address fields in place and sets its composed {@code address}.
59	     * When a structured {@code addressLine1} is present it is preferred; otherwise the flat
60	     * {@code address} is normalized and the structured lines are cleared.
61	     */
62	    public void resolve(Owner owner) {
63	        String line1 = addressNormalizer.normalize(owner.getAddressLine1());
64	        if (line1.isEmpty()) {
65	            owner.setAddressLine1(null);
66	            owner.setAddressLine2(null);
67	            owner.setAddress(addressNormalizer.normalize(owner.getAddress()));
68	            return;
69	        }
70	        String line2 = addressNormalizer.normalize(owner.getAddressLine2());
71	        owner.setAddressLine1(line1);
72	        owner.setAddressLine2(line2.isEmpty() ? null : line2);
73	        owner.setAddress(line2.isEmpty() ? line1 : line1 + " " + line2);
74	    }
75	}
