17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.time.DayOfWeek;
20	import java.time.LocalDate;
21	import java.util.Set;
22	
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Rolls a date forward onto a business day: when the given date falls on a Saturday, a
27	 * Sunday or a listed public holiday it is advanced to the next non-holiday weekday,
28	 * otherwise it is returned unchanged.
29	 */
30	@Component
31	public class BusinessDayAdjuster {
32	
33	    /** Fixed public holidays that the business-day roll skips. */
34	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
35	            LocalDate.parse("2026-01-01"), LocalDate.parse("2026-01-26"),
36	            LocalDate.parse("2026-04-25"), LocalDate.parse("2026-12-25"), LocalDate.parse("2026-12-28"));
37	
38	    /**
39	     * Return {@code date} if it is a business day, otherwise the next non-holiday weekday.
40	     *
41	     * @param date the date to adjust
42	     * @return the same date when it is a business day, or the next weekday that is neither a
43	     *         weekend nor a public holiday
44	     */
45	    public LocalDate toBusinessDay(LocalDate date) {
46	        LocalDate adjusted = date;
47	        while (!isBusinessDay(adjusted)) {
48	            adjusted = adjusted.plusDays(1);
49	        }
50	        return adjusted;
51	    }
52	
53	    private boolean isBusinessDay(LocalDate date) {
54	        return date.getDayOfWeek() != DayOfWeek.SATURDAY && date.getDayOfWeek() != DayOfWeek.SUNDAY
55	                && !PUBLIC_HOLIDAYS.contains(date);
56	    }
57	}
