17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.List;
20	import java.util.Locale;
21	
22	import org.springframework.samples.petclinic.model.Owner;
23	import org.springframework.samples.petclinic.model.OwnerIdentityVersion;
24	import org.springframework.samples.petclinic.service.ClinicService;
25	import org.springframework.stereotype.Component;
26	
27	/**
28	 * Household identity for owners: two owners belong to the same household when their last name
29	 * (compared case-insensitively, with runs of whitespace collapsed) and postcode match. The
30	 * {@code householdId} is derived deterministically from those two fields, so owners with the
31	 * same last name and postcode share it automatically without any explicit linking. Provides the
32	 * shared lookup and identifier logic reused by the duplicate guard and by the household-size
33	 * queries that key off {@code householdId}.
34	 */
35	@Component
36	public class Households {
37	
38	    /** Number of leading SHA-256 hex characters that make up a household identifier. */
39	    private static final int ID_LENGTH = 12;
40	
41	    private final ClinicService clinicService;
42	
43	    private final Sha256 sha256;
44	
45	    public Households(ClinicService clinicService, Sha256 sha256) {
46	        this.clinicService = clinicService;
47	        this.sha256 = sha256;
48	    }
49	
50	    /**
51	     * Existing owners that share {@code candidate}'s household (same {@link #householdId(Owner)
52	     * household identifier}). Intended for a not-yet-persisted candidate, so the candidate never
53	     * appears in the result. Soft-deleted owners are excluded: they no longer count as household
54	     * members for duplicate detection.
55	     */
56	    public List<Owner> findMembers(Owner candidate) {
57	        String householdId = householdId(candidate);
58	        return clinicService.findOwnerByLastNameIgnoreCase(candidate.getLastName()).stream()
59	            .filter(existing -> !existing.isDeleted())
60	            .filter(existing -> householdId.equals(householdId(existing)))
61	            .toList();
62	    }
63	
64	    /**
65	     * The stable identifier every owner in {@code owner}'s household shares: the first
66	     * {@value #ID_LENGTH} hex characters of {@code SHA-256(V2 + '|' + normalizedLastName + '|' +
67	     * postcode)}, with the {@link OwnerIdentityVersion#TAG version tag} mixed in as the leading
68	     * segment. The same last name and postcode always yield the same id.
69	     */
70	    public String householdId(Owner owner) {
71	        String key = OwnerIdentityVersion.TAG + "|" + normalize(owner.getLastName())
72	            + "|" + segment(owner.getPostcode());
73	        return sha256.hex(key).substring(0, ID_LENGTH);
74	    }
75	
76	    /**
77	     * Canonicalize the last name for household comparison: {@code null} becomes empty, surrounding
78	     * whitespace is trimmed, internal whitespace runs collapse to a single space, and the result
79	     * is lower-cased.
80	     */
81	    private String normalize(String value) {
82	        if (value == null) {
83	            return "";
84	        }
85	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
86	    }
87	
88	    private String segment(String value) {
89	        return value == null ? "" : value;
90	    }
91	}
