18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.service.ClinicService;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Guards owner creation against re-registration of the same identity. Two owners are the same
25	 * identity when their {@link OwnerIdentity identity key} matches (same normalized telephone, email
26	 * and last-name sound); a candidate that collides with an existing, non-deleted owner is rejected.
27	 * Owners differing in any of those fields — including household members with different telephones —
28	 * are distinct identities and are left to {@link PossibleDuplicateDetector} to flag softly.
29	 */
30	@Component
31	public class DuplicateIdentityValidator {
32	
33	    private final ClinicService clinicService;
34	
35	    private final OwnerIdentity ownerIdentity;
36	
37	    public DuplicateIdentityValidator(ClinicService clinicService, OwnerIdentity ownerIdentity) {
38	        this.clinicService = clinicService;
39	        this.ownerIdentity = ownerIdentity;
40	    }
41	
42	    /**
43	     * Reject {@code candidate} when an existing, non-deleted owner already carries the same identity
44	     * key.
45	     *
46	     * @param candidate the owner about to be created, with its fields already normalized
47	     * @throws DuplicateIdentityException if a non-deleted owner shares the candidate's identity key
48	     */
49	    public void validate(Owner candidate) {
50	        String identityKey = ownerIdentity.key(candidate);
51	        boolean duplicate = clinicService.findAllOwners().stream()
52	            .filter(existing -> !existing.isDeleted())
53	            .anyMatch(existing -> identityKey.equals(ownerIdentity.key(existing)));
54	        if (duplicate) {
55	            throw new DuplicateIdentityException(identityKey);
56	        }
57	    }
58	}
