17	package org.springframework.samples.petclinic.rest.controller;
18	
19	import java.util.Comparator;
20	
21	import org.springframework.samples.petclinic.model.Owner;
22	import org.springframework.samples.petclinic.service.ClinicService;
23	import org.springframework.stereotype.Component;
24	
25	/**
26	 * Flags soft duplicates on owner creation. Unlike the hard {@link DuplicateIdentityValidator}
27	 * (which rejects an owner that re-registers an existing identity key), a soft match never blocks
28	 * creation: when an existing owner has a different identity key but shares the candidate's last-name
29	 * sound ({@link Soundex}) and postcode, the candidate is recorded as a possible duplicate of that
30	 * owner.
31	 */
32	@Component
33	public class PossibleDuplicateDetector {
34	
35	    private final ClinicService clinicService;
36	
37	    private final OwnerIdentity ownerIdentity;
38	
39	    private final Soundex soundex;
40	
41	    public PossibleDuplicateDetector(ClinicService clinicService, OwnerIdentity ownerIdentity,
42	            Soundex soundex) {
43	        this.clinicService = clinicService;
44	        this.ownerIdentity = ownerIdentity;
45	        this.soundex = soundex;
46	    }
47	
48	    /**
49	     * Record whether {@code candidate} is a possible duplicate of an existing owner. Sets
50	     * {@code possibleDuplicate} true and {@code possibleDuplicateOf} to the earliest existing owner
51	     * whose identity key differs but whose last-name sound and postcode match the candidate;
52	     * otherwise sets {@code possibleDuplicate} false and leaves {@code possibleDuplicateOf} unset.
53	     *
54	     * @param candidate the owner about to be created, with its fields already normalized
55	     */
56	    public void detect(Owner candidate) {
57	        Owner match = findMatch(candidate);
58	        candidate.setPossibleDuplicate(match != null);
59	        if (match != null) {
60	            candidate.setPossibleDuplicateOf(match.getId());
61	        }
62	    }
63	
64	    private Owner findMatch(Owner candidate) {
65	        if (candidate.getPostcode() == null) {
66	            return null;
67	        }
68	        String identityKey = ownerIdentity.key(candidate);
69	        String lastNameSound = soundex.of(candidate.getLastName());
70	        return clinicService.findAllOwners().stream()
71	            .filter(existing -> !existing.isDeleted())
72	            .filter(existing -> candidate.getPostcode().equals(existing.getPostcode()))
73	            .filter(existing -> lastNameSound.equals(soundex.of(existing.getLastName())))
74	            .filter(existing -> !identityKey.equals(ownerIdentity.key(existing)))
75	            .min(Comparator.comparing(Owner::getId))
76	            .orElse(null);
77	    }
78	}
