28	/**
29	 * Emits audit output to the dedicated {@code AUDIT} logger whenever an owner is successfully
30	 * created. Two entries are produced per create:
31	 * <ul>
32	 *   <li>a human-readable line carrying the persisted owner's id, its generated
33	 *       {@code memberId}, its {@code registrationDate} and its derived
34	 *       {@code membershipLevel}; and</li>
35	 *   <li>an immutable structured {@link OwnerCreatedEvent} serialized as JSON, so the create
36	 *       can be reconciled against the audit log without depending on any
37	 *       implementation-specific hook.</li>
38	 * </ul>
39	 */
40	@Component
41	public class OwnerAuditLogger {
42	
43	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
44	
45	    private final MembershipLevelEvaluator membershipLevelEvaluator;
46	
47	    private final ObjectMapper objectMapper = new ObjectMapper();
48	
49	    /** Assigns each created owner a monotonically increasing sequence number. */
50	    private final AtomicLong sequence = new AtomicLong();
51	
52	    public OwnerAuditLogger(MembershipLevelEvaluator membershipLevelEvaluator) {
53	        this.membershipLevelEvaluator = membershipLevelEvaluator;
54	    }
55	
56	    /**
57	     * Record the successful creation of an owner.
58	     *
59	     * @param owner the persisted owner (id, memberId and registrationDate populated)
60	     */
61	    public void logCreated(Owner owner) {
62	        Integer membershipLevel = membershipLevelEvaluator.levelFor(owner);
63	        AUDIT.info("Owner created: id={} memberId={} registrationDate={} membershipLevel={}",
64	            owner.getId(), owner.getMemberId(), owner.getRegistrationDate(), membershipLevel);
65	        OwnerCreatedEvent event = OwnerCreatedEvent.of(sequence.incrementAndGet(), owner, membershipLevel);
66	        AUDIT.info(objectMapper.writeValueAsString(event));
67	    }
68	}
