18	
19	import org.springframework.samples.petclinic.model.Owner;
20	import org.springframework.samples.petclinic.model.OwnerIdentityVersion;
21	import org.springframework.stereotype.Component;
22	
23	/**
24	 * Owner identity: the single derived key that consolidates telephone, email and last name into
25	 * one value used for duplicate detection. Two owners are the same identity only when their whole
26	 * key matches; because the (normalized) telephone is part of the key, two members of one household
27	 * with different telephones have distinct identities.
28	 * <p>
29	 * The key is the SHA-256 hex digest of {@code V2 + '|' + normalizedTelephone + '|' + lowerEmail +
30	 * '|' + soundex(lastName)}, built from the owner's already-canonical fields (telephone in E.164
31	 * form, email trimmed and lower-cased) with the {@link OwnerIdentityVersion#TAG version tag} mixed
32	 * in as the leading segment. A {@code null} field contributes an empty segment so distinct fields
33	 * cannot collide across the {@code '|'} separators.
34	 */
35	@Component
36	public class OwnerIdentity {
37	
38	    private final Soundex soundex;
39	
40	    private final Sha256 sha256;
41	
42	    public OwnerIdentity(Soundex soundex, Sha256 sha256) {
43	        this.soundex = soundex;
44	        this.sha256 = sha256;
45	    }
46	
47	    /**
48	     * The identity key for {@code owner}: the SHA-256 hex of the {@link OwnerIdentityVersion#TAG
