26	 * already holds. When the base id is free it is returned unchanged; otherwise {@code '-<n>'} is
27	 * appended, using the smallest {@code n} of 2 or more that yields an id no existing owner holds.
28	 */
29	@Component
30	public class MemberIdDeduplicator {
31	
32	    /**
33	     * De-duplicate {@code baseId} against the ids already in use.
34	     *
35	     * @param baseId      the freshly generated member id
36	     * @param existingIds the member ids already held by existing owners
37	     * @return {@code baseId} when it is free, otherwise {@code '<baseId>-<n>'} with the smallest
38	     * {@code n} of 2 or more that is not already taken
39	     */
40	    public String deDuplicate(String baseId, Collection<String> existingIds) {
41	        Set<String> taken = new HashSet<>(existingIds);
42	        if (!taken.contains(baseId)) {
43	            return baseId;
44	        }
45	        for (int n = 2; ; n++) {
46	            String candidate = baseId + "-" + n;
47	            if (!taken.contains(candidate)) {
48	                return candidate;
49	            }
50	        }
51	    }
